"""Publish the continued silhouette fit and independently checked joint roots."""
from pathlib import Path
import hashlib,json,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-joints-r8'
row=json.loads((OUT/'refinement-metrics.json').read_text());ID=row['id']
checks=json.loads((OUT/'verification.json').read_text());contacts=json.loads((OUT/'attachment-verification.json').read_text());joint=json.loads((OUT/'joint-verification.json').read_text());direction=json.loads((OUT/'side-orientation.json').read_text())
closing=json.loads((OUT/'closing-face-verification.json').read_text());assert closing['result']=='PASS' and closing['sampled_points']==8064 and closing['poses']==36
assert row['triangles']==checks['triangles']==1800 and contacts['result']=='PASS' and contacts['endpoints']==58 and contacts['sampled_poses']==35
assert joint['result']=='PASS' and joint['supported_arm_roots']==2 and joint['supported_finger_roots']==6
assert checks['source_sha256']==direction['source_sha256']==hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest() and direction['camera_direction'][0]<0
auth=json.loads((OUT/'silhouette-authoring.json').read_text());auth.update(scope='inherited r7 global head/body fit; r8 shoulder and joint refinements recorded in joint-authoring.json',torso_width_fit=1.10)
(OUT/'silhouette-authoring.json').write_text(json.dumps(auth,indent=2)+'\n',encoding='utf-8')
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — shoulder and joint silhouette r8</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.reference img{{height:650px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}.reference img{{height:500px}}}}</style>
<h1>Rift Titan — shoulder and joint silhouette r8</h1>
<p>The shoulder plates now slope and hang more steeply. The elbows sit farther back and the wrists project forward; arm plates follow those angles in three dimensions, with individual tapered stone sections. The leg stance is slightly closer, the knees project forward, and the fingers are shorter and seated into the palms. Foot thickness was restored after the first render read too flat. The cleft head and both torso rings remain.</p>
<p><strong>Front/head left, back right in every side view.</strong> The same guarded cameras are used for the preserved r7 and current r8 comparison.</p>
<p><strong>1,800 triangles · 1.500× native Stone Golem · soft cap 1,800</strong>. One mesh/material, four 512px maps, eight original bone identities and seven retained actions. Fifty existing body supports plus eight new arm/digit root contacts pass 35 sampled poses. Proximal arm roots stay seated in the shoulders, with a sparse Body/Arm blend below them. This remains a silhouette candidate; surface texture detail is on hold.</p>
<h2>Front silhouette</h2><div class="pair reference"><figure><img src="concept-front.png" alt="Supplied front concept"><figcaption>Concept front</figcaption></figure><figure><img src="{ID}--front-reference.png" alt="Current frontal clay silhouette"><figcaption>Current r8 — steeper shoulders, revised arms and stance</figcaption></figure></div>
<h2>Left-facing side</h2><div class="pair reference"><figure><img src="concept-side.png" alt="Supplied left-facing side concept"><figcaption>Concept side — front left, back right</figcaption></figure><figure><img src="{ID}--side-reference-clay.png" alt="Current left-facing clay silhouette"><figcaption>Current r8 — backward elbow, forward wrist and stone plates following the arm</figcaption></figure></div>
<h2>Previous and current — matched cameras</h2><div><button data-view="front-clay">Front clay</button><button data-view="side-clay">True side clay</button><button data-view="side-reference">Left-facing angled side</button></div><div class="pair"><figure><img id="before" src="before/underworld-boss-rift-titan-silhouette-r7--front-clay.png" alt="Preserved r7"><figcaption>Previous r7</figcaption></figure><figure><img id="after" src="{ID}--front-clay.png" alt="Current r8"><figcaption>Current r8 — existing geometry reshaped; no triangle increase</figcaption></figure></div>
<h2>Adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Full adopted concept sheet">
<p>The concept's finer rock fragmentation and silhouette irregularity remain unfinished. The user's “still so far off” remains the review state; neither positive progress nor passing geometry checks establishes adequate boss acceptance. Native loading, full animation deformation and live performance are separate pending checks.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--three-quarter.png">Surface view</a> · <a href="{ID}--detail.png">Torso close-up</a> · <a href="{ID}--attack.png">Attack pose</a> · <a href="verification.json">Geometry/export checks</a> · <a href="attachment-verification.json">All support checks</a> · <a href="joint-verification.json">Arm/digit root and blend checks</a> · <a href="closing-face-verification.json">Closing-face checks</a> · <a href="joint-authoring.json">Changes</a> · <a href="silhouette-measurements.json">Saved proportions</a> · <a href="side-orientation.json">Camera orientation</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='before/underworld-boss-rift-titan-silhouette-r7--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_wrapped_torso.py','tools/rift_titan_silhouette_fit.py','tools/rift_titan_joint_silhouette.py','tools/refine-rift-titan-joints-r8.py','tools/review-rift-titan-silhouette-r7.py','tools/review-rift-titan-joints-r8.py','tools/verify-rift-titan-joints-r8.py','tools/publish-rift-titan-joints-r8.py',row['source'],'assets/models/studies/underworld-boss-rift-titan-silhouette-r7.blend','docs/art/creature-concepts/2026-10-03/the-rift-titan.png']+[p.relative_to(ROOT).as_posix() for p in OUT.glob('concept-*.png')]
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},acceptance='continued unaccepted silhouette candidate; adequate boss tally remains 1/6'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
for view in ('front-clay','side-clay','side-reference'):
 assert (OUT/'before'/('underworld-boss-rift-titan-silhouette-r7--'+view+'.png')).is_file()
 assert (OUT/(ID+'--'+view+'.png')).is_file()
print('VERIFIED r8 comparison links, left-facing side, 58 supports, cap and source provenance')
